from control import s
import numpy as np
from scipy.spatial.transform import Rotation
ln=s['links']['names'];parents=s['links']['parent'];axes=np.array(s['proprio']['axis']);points=np.array(s['proprio']['position_m']);mass=np.array(s['links']['mass_kg']);com=np.array(s['links']['com_m']);
def fk(q):
 Ts=[np.eye(4)];
 for i in range(69):
  R=Rotation.from_rotvec(axes[i]/np.linalg.norm(axes[i])*q[i]).as_matrix();T=np.eye(4);T[:3,:3]=R;T[:3,3]=points[i]-R@points[i];Ts.append(Ts[ln.index(parents[i+1])]@T)
 return np.array(Ts)
def state(q,g):
 Ts=fk(q);pts=np.einsum('nij,nj->ni',Ts[:,:3,:3],com)+Ts[:,:3,3];COM=(pts*mass[:,None]).sum(0)/mass.sum();feet=[]
 for name in ['left_ankle_link','right_ankle_link']:
  bounds=np.array(s['links']['feet'][name]);point=np.mean(bounds,axis=0);T=Ts[ln.index(name)];feet.append(T[:3,:3]@point+T[:3,3])
 foot=np.mean(feet,axis=0);g=np.array(g);h=np.array([1.,0,0]);h-=g*g[0];h/=np.linalg.norm(h);return np.dot(COM-foot,h),COM,foot
if __name__=='__main__':
 import sys
 from rcb_client import Robot
 r=Robot();o=r.observe(False);print(state(o['proprio']['joint_pos'],o['imu']['gravity']))
PY
