import sys
from kin import *
from scipy.optimize import least_squares
qactual=np.load('/app/output/side_actual.npy');idx=np.arange(11,18);lim=np.array(s['qpos']['range'])[[11,12,13,14,15,21,22]];pi=ln.index('lh_palm');qstart=qactual[idx];T=fk(qactual)[pi];P0=T[:3,:3]@com[pi]+T[:3,3];R0=T[:3,:3]
def pose(x):
 T=np.eye(4);rt=Rotation.from_rotvec([0,0,qactual[10]]).as_matrix();T[:3,:3]=rt
 for j,k in enumerate(idx):
  R=Rotation.from_rotvec(axes[k]/np.linalg.norm(axes[k])*x[j]).as_matrix();U=np.eye(4);U[:3,:3]=R;U[:3,3]=points[k]-R@points[k];T=T@U
 return T[:3,:3]@com[pi]+T[:3,3],T[:3,:3]
def solve(P,x=qstart):
 def fun(v):
  pos,R=pose(v);return np.r_[(pos-P)*10,Rotation.from_matrix(R0.T@R).as_rotvec()]
 z=least_squares(fun,np.clip(x,lim[:,0]+1e-6,lim[:,1]-1e-6),bounds=(lim[:,0],lim[:,1]),max_nfev=70)
 return z.x,np.linalg.norm(fun(z.x))
if __name__=='__main__':
 for dx in [.05,.1,.15]:
  for dz in [-.08,0,.08]:
   x,e=solve(P0+np.array([dx,0,dz]));print(dx,dz,'err',round(e,3),'q',np.round(x,2))
